def intent(key, *, kind, validates, scenario, predicate, invalid, unknown, env, owner_task, executor=None,
           acceptance_owner, after=(), hints, groups, required_at="checkpoint-and-candidate"):
    return X(key), {
        "schema_version": 1, "kind": kind, "validates": list(validates), "scenario": scenario,
        "evidence": {"predicate": predicate, "invalid": invalid, "unknown": unknown},
        "environment": list(env), "obligation_owner_task": T(owner_task),
        "evidence_executor_task": T(executor or owner_task), "acceptance_owner": acceptance_owner,
        "activation": {"after_accepted": [T(a) for a in after]}, "target_hints": list(hints),
        "affected_check_groups": norm(groups, EXTRA.get(key, ())), "required_at": required_at,
    }

